import{_ as a,o as t,c as i,a2 as n}from"./chunks/framework.Dz59sQ41.js";const m=JSON.parse('{"title":"Admin internals","description":"","frontmatter":{},"headers":[],"relativePath":"docs/admin-internals.md","filePath":"docs/admin-internals.md"}'),s={name:"docs/admin-internals.md"};function o(r,e,d,l,c,h){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="admin-internals" tabindex="-1">Admin internals <a class="header-anchor" href="#admin-internals" aria-label="Permalink to &quot;Admin internals&quot;">​</a></h1><p>What to know before changing admin code: the decisions and the traps. The routes, filters, status codes and fields are in the OpenAPI document, generated from the code, so they aren&#39;t repeated here. The rules these enforce are in <a href="./admin">the admin area</a>.</p><h2 id="access" tabindex="-1">Access <a class="header-anchor" href="#access" aria-label="Permalink to &quot;Access&quot;">​</a></h2><ul><li>Admin is a <code>role</code> on the account, not a scope (<a href="./adr/0020-every-credential-resolves-to-one-caller">ADR 0020</a>). The server accepts the access cookie only from the website client (<a href="./the-api#signing-in">the API</a>).</li><li>A write whose <code>Origin</code> isn&#39;t the website&#39;s gets 403. This is the CSRF defence.</li><li>A member who signs in on the website gets the same answer as any refusal, so the role never leaks.</li><li><code>ADMIN_EMAIL</code> is read at start-up, and the promotion is an <code>AdminAction</code>.</li></ul><h2 id="accounts" tabindex="-1">Accounts <a class="header-anchor" href="#accounts" aria-label="Permalink to &quot;Accounts&quot;">​</a></h2><ul><li><code>AdminAccounts.list</code> reads every account row and cuts the page in memory. That&#39;s enough for a back office. Move it into SQL if accounts reach the hundreds of thousands.</li><li>Confirming an account&#39;s email by hand (from Accounts) has the same effect as the link: the account can sign in, its pending links stop working and a phone waiting for the link hears it.</li><li>Disabling revokes every access and refresh token. Deleting runs the same code as the user&#39;s own deletion.</li></ul><h2 id="settings-and-mail" tabindex="-1">Settings and mail <a class="header-anchor" href="#settings-and-mail" aria-label="Permalink to &quot;Settings and mail&quot;">​</a></h2><ul><li>Settings are one row each in the <code>settings</code> table (<code>ServerSettings</code>). Only non-secret ones go there, so the SMTP details stay in the environment.</li><li>Every email goes through <code>SettingsMailer</code>, which reads <code>mail-from</code> when it sends. That&#39;s why a saved address applies with no restart.</li><li>Mail is configured when <code>SMTP_HOST</code> is set. Without it, sending fails with <code>No mail server is set: SMTP_HOST is unset</code>, and the error isn&#39;t printed to the log.</li><li><code>SettingsMailer.last</code> keeps the last send in memory, so a restart forgets it.</li><li>The public <code>GET /api/v1/status</code> must never say how the server is configured. A test holds it to that.</li></ul><h2 id="catalog" tabindex="-1">Catalog <a class="header-anchor" href="#catalog" aria-label="Permalink to &quot;Catalog&quot;">​</a></h2><ul><li>Revisions live in <code>catalog_exercise_revision</code>, and publishing writes rows only for the exercises it names (<a href="./adr/0030-the-catalog-changes-by-exercise-revision-not-by-catalog-version">ADR 0030</a>).</li><li>Content, translation and lifecycle are separate dimensions in the list&#39;s filters. Don&#39;t fold one into another.</li></ul><h2 id="audit-log" tabindex="-1">Audit log <a class="header-anchor" href="#audit-log" aria-label="Permalink to &quot;Audit log&quot;">​</a></h2><ul><li>An admin action is an <code>AdminAction</code> event sent through http4k&#39;s <code>Events</code>. One sink stores it in <code>admin_audit</code> and another prints it to the server log. Tests check it with <code>RecordingEvents</code>. Every admin write must emit one.</li><li><code>EmailAddress</code> is a values4k type that prints masked, so an address that reaches a log by accident stays hidden. Read the real one with <code>.value</code> only where needed. An event never carries a password or an unmasked address.</li></ul>',12)])])}const g=a(s,[["render",o]]);export{m as __pageData,g as default};
